const item = $input.item.json;

// Primeiro nome do lead
const nome = (item.nome_cliente || '').trim().split(' ')[0] || 'Cliente';
const email = item.email || '';

// Formatar celular em E.164 (+55XXXXXXXXXX)
const digits = (item.celular || '').replace(/\D/g, '');
let telefone;
if (digits.startsWith('55') && digits.length >= 12) {
  telefone = '+' + digits;
} else if (digits.length >= 10) {
  telefone = '+55' + digits;
} else {
  throw new Error('[02a] Celular inválido para agendamento ' + item.id);
}

// Obter contact_id via clint_contact_uuid ou fallback ao deal
let contact_id = item.clint_contact_uuid || null;

if (!contact_id && item.clint_card_id) {
  const token = 'U2FsdGVkX18o3kwB1pZCF/BjjfgN8GgFjmt5Fkzf06JXZIbAkVToB6ZLKPIljW7mSS0ESoxnErXsL9DXE+ZGVg==';
  try {
    const deal = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.clint.digital/v1/deals/' + item.clint_card_id,
      headers: { 'api-token': token },
      json: true
    });
    const c = deal.data?.contact || deal.contact || {};
    contact_id = c.id || null;
  } catch(e) {
    console.log('[02a] Erro ao buscar deal: ' + e.message);
  }
}

if (!contact_id) {
  throw new Error('[02a] Sem contact_id para agendamento ' + item.id);
}

return { json: { agendamento_id: item.id, clint_card_id: item.clint_card_id, contact_id, nome, email, telefone } };
